import React, { useEffect, useState } from 'react';

// --- MOCK LOGIC: This logic would typically live on the Backend/Server ---
// Define criteria for badge assignment based on the latest image and your previous criteria
const BADGE_CRITERIA = {
  // Volunteer Badges (assuming these points are still lower as they were not updated in the image)
  volunteer: [
    { points: 20, title: "Bronze Volunteer", badge_key: "BRONZE_VOLUNTEER", description: "Earned after 20 volunteer points" },
    { points: 50, title: "Silver Volunteer", badge_key: "SILVER_VOLUNTEER", description: "Earned after 50 volunteer points" },
    { points: 100, title: "Gold Volunteer", badge_key: "GOLD_VOLUNTEER", description: "Earned after 100 volunteer points" },
  ],
  // Donor Badges - UPDATED based on the new image's "₹1000+" for Silver Donor
  donor: [
    // Assuming 1000 points (₹) for Silver Donor as per your image
    { points: 1000, title: "Silver Donor", badge_key: "SILVER_DONOR", description: "₹1000+" },
    // Adjusting Gold and Platinum to be higher than Silver, reflecting a currency scale
    { points: 2000, title: "Gold Donor", badge_key: "GOLD_DONOR", description: "₹2000+" },
    { points: 5000, title: "Platinum Donor", badge_key: "PLATINUM_DONOR", description: "₹5000+" },
  ],
};

/**
 * Mocks the backend logic to check if a user qualifies for a new badge.
 * This version awards the *first* eligible badge found (lowest threshold met)
 * if existingBadges array is empty. If multiple badges are already present,
 * it will still try to award the highest new one.
 * @param {number} currentPoints The user's current points (interpreted as currency for Donor).
 * @param {string} badgeType 'volunteer' or 'donor'
 * @param {Array<Object>} existingBadges List of badges the user already has.
 * @returns {Object|null} The newly awarded badge object, or null.
 */
function checkAndAwardBadge(currentPoints, badgeType, existingBadges) {
    const criteria = BADGE_CRITERIA[badgeType];
    const existingKeys = new Set(existingBadges.map(b => b.badge_key || b.key));

    // Sort criteria from lowest to highest points if we only want to award the first met badge.
    // If you want to award the HIGHEST possible badge, sort highest to lowest.
    // Given your image shows Silver Donor for 1010 points, even though Platinum (200) would be met by previous criteria,
    // I will assume it should award the *first* (lowest point) eligible badge if no badges are present.
    const sortedCriteria = [...criteria].sort((a, b) => a.points - b.points);

    // If no badges are currently present, check for the first one met.
    if (existingBadges.length === 0) {
        for (const badge of sortedCriteria) {
            if (currentPoints >= badge.points) {
                return { 
                    title: badge.title, 
                    badge_key: badge.badge_key,
                    description: badge.description, // Use specific description from criteria
                };
            }
        }
    } else {
        // If user already has badges, we should still ensure they have the highest *new* one.
        // Re-sort to find the highest eligible badge they *don't* have.
        const highestSortedCriteria = [...criteria].sort((a, b) => b.points - a.points);
        for (const badge of highestSortedCriteria) {
            if (currentPoints >= badge.points && !existingKeys.has(badge.badge_key)) {
                return { 
                    title: badge.title, 
                    badge_key: badge.badge_key,
                    description: badge.description,
                };
            }
        }
    }
    
    return null;
}
// --- END MOCK LOGIC ---

export default function AchievementsPanel({ token, me = {}, role = 'user', onViewNgo, setMsg }) {
  const [achievements, setAchievements] = useState(null);
  const [badges, setBadges] = useState([]);
  
  const currentPoints = me?.points || 0; 
  
  useEffect(() => {
    if (!token) return;

    const apiBase = process.env.REACT_APP_API || 'http://localhost:4000';
    const userUrl = role === 'NGO' ? `${apiBase}/api/ngo/achievements` : `${apiBase}/api/actions/achievements`;

    fetch(userUrl, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { 
        let fetchedBadges = d?.badges || [];
        
        // --- CLIENT-SIDE MOCK BADGE AWARD CHECK ---
        // We assume the points are 'donor' points for the 1010 point user
        const awardedBadge = checkAndAwardBadge(currentPoints, 'donor', fetchedBadges); 
        
        if (awardedBadge) {
          // Add the newly awarded badge to the front of the list
          fetchedBadges = [awardedBadge, ...fetchedBadges];
          setMsg && setMsg({ type: 'success', text: `🎉 Congratulations! You earned the "${awardedBadge.title}" badge!` });
        }
        // --- END CLIENT-SIDE MOCK ---

        setAchievements(d); 
        setBadges(fetchedBadges); 
      })
      .catch(err => { 
        console.error('Achievements load error', err); 
        setAchievements({ badges: [] }); 
      });

    // Load persisted badges as well (user-badges)
    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/user-badges', { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { 
        // Only update if initial fetch was empty or if the newly awarded badge is not yet in 'badges' state
        if (d?.badges && badges.length === 0) { 
            setBadges(d.badges); 
        }
      })
      .catch(() => {});
  }, [token, role, currentPoints, setMsg, badges.length]);

  return (
    <div style={{ width: 320, flexShrink: 0 }}>
      <h3 style={{ marginBottom: 12 }}>Achievements</h3>

      <div style={{
        background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
        padding: 18,
        borderRadius: 12,
        color: '#fff',
        textAlign: 'center',
        boxShadow: '0 8px 30px rgba(2,6,23,0.08)'
      }}>
        <div style={{ fontSize: 42, fontWeight: 800 }}>{currentPoints}</div>
        <div style={{ opacity: 0.9, marginTop: 6 }}>POINTS</div>
      </div>

      <div style={{ marginTop: 14 }}>
        <h4 style={{ marginBottom: 8 }}>Badges</h4>

        {!achievements && (
          <div style={{ fontSize: 13, color: '#666' }}>Loading badges...</div>
        )}

        {/* If achievements loaded and no badges are found (even after mock check) */}
        {achievements && badges.length === 0 && (
          <div style={{ padding: 14, borderRadius: 10, background: '#fff', color: '#666', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>No badges yet — participate to earn rewards.</div>
        )}

        {badges.length > 0 && (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(2,1fr)",
              gap: 10,
              marginTop: 10,
            }}
          >
            {badges.map((b, i) => {
              // Default icon mapping
              const iconMap = {
                "Gold Volunteer": "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
                "Silver Volunteer": "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
                "Bronze Volunteer": "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105",

                // Updated Donor badge icons based on typical imagery (you can replace with your own)
                "Platinum Donor": "https://tse3.mm.bing.net/th/id/OIP.Imd7GlakFy5b_od5xomrDAHaHa?pid=Api&P=0&h=180", // Placeholder for Platinum
                "Gold Donor": "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121", // Placeholder for Gold
                "Silver Donor": "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120", // Placeholder for Silver
              };

              const finalIcon =
                b.icon || iconMap[b.title] || iconMap[b.badge_key] || "";

              return (
                <div
                  key={b.badge_key || b.key || i}
                  style={{
                    background: "#fff",
                    padding: 10,
                    borderRadius: 10,
                    boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
                    border: "1px solid #f1f5f9",
                    textAlign: "center",
                  }}
                >
                  {finalIcon && (
                    <img
                      src={finalIcon}
                      alt={b.title}
                      style={{
                        width: 45,
                        height: 45,
                        marginBottom: 6,
                        objectFit: "contain",
                      }}
                    />
                  )}

                  <div style={{ fontWeight: 700, fontSize: 14 }}>
                    {b.title || b.badge_key}
                  </div>

                  <div style={{ fontSize: 12, color: "#555" }}>
                    {b.description || b.desc}
                  </div>
                </div>
              );
            })}
          </div>
        )}

      </div>

      {onViewNgo && (
        <div style={{ marginTop: 18 }}>
          <button onClick={() => onViewNgo()} style={{ width: '100%', padding: '10px 12px', borderRadius: 10, background: '#2563eb', color: '#fff', border: 0, cursor: 'pointer' }}>View Hosting NGOs</button>
        </div>
      )}
    </div>
  );
}
